	String hidden = "_hidden";
	String show = "_show";
	String auto_hide = "_auto_hide";
	String storage = "_storage";
	String panel_priority = "panel_priority";
	String version = "version";
	String home = "home";
	String lunar_chest_hide_close = "lunar_chest_hide_close";

