		@ConfigItem(
			keyName = inventory + hidden,
			name = "Hidden items",
			description = "Names of the items to hide in the inventory overlay",
			section = inventory,
			position = 4
		) default String getInventoryHidden() { return ""; }

		@ConfigItem(
